// Enhanced currency formatting utilities for UAE Dirham

/**
 * Format number as UAE Dirham currency
 * @param {number} amount - The amount to format
 * @param {object} options - Formatting options
 * @returns {string} Formatted currency string
 */
export function formatAED(amount, options = {}) {
  const {
    minimumFractionDigits = 0,
    maximumFractionDigits = 2,
    showSymbol = true,
    showCode = false,
    compact = false
  } = options;

  if (amount === null || amount === undefined || isNaN(amount)) {
    return showSymbol ? 'د.إ 0' : '0';
  }

  const numericAmount = Number(amount);

  // Handle compact formatting for large numbers
  if (compact && Math.abs(numericAmount) >= 1000) {
    if (Math.abs(numericAmount) >= 1000000) {
      const millions = numericAmount / 1000000;
      return `${millions.toFixed(1)}م ${showSymbol ? 'د.إ' : ''}`;
    } else if (Math.abs(numericAmount) >= 1000) {
      const thousands = numericAmount / 1000;
      return `${thousands.toFixed(1)}ك ${showSymbol ? 'د.إ' : ''}`;
    }
  }

  // Format with Arabic numerals and proper grouping
  const formatter = new Intl.NumberFormat('ar-AE', {
    style: 'decimal',
    minimumFractionDigits,
    maximumFractionDigits,
    useGrouping: true
  });

  const formattedNumber = formatter.format(Math.abs(numericAmount));
  const sign = numericAmount < 0 ? '-' : '';
  
  if (showCode) {
    return `${sign}${formattedNumber} درهم إماراتي`;
  } else if (showSymbol) {
    return `${sign}${formattedNumber} د.إ`;
  } else {
    return `${sign}${formattedNumber}`;
  }
}

/**
 * Format currency for display in tables and cards
 * @param {number} amount - The amount to format
 * @returns {string} Formatted currency string
 */
export function formatCurrencyDisplay(amount) {
  return formatAED(amount, { 
    minimumFractionDigits: 0, 
    maximumFractionDigits: 0,
    showSymbol: true 
  });
}

/**
 * Format currency for detailed financial reports
 * @param {number} amount - The amount to format
 * @returns {string} Formatted currency string with decimals
 */
export function formatCurrencyDetailed(amount) {
  return formatAED(amount, { 
    minimumFractionDigits: 2, 
    maximumFractionDigits: 2,
    showSymbol: true 
  });
}

/**
 * Format currency in compact form for charts and summaries
 * @param {number} amount - The amount to format
 * @returns {string} Compact formatted currency string
 */
export function formatCurrencyCompact(amount) {
  return formatAED(amount, { 
    compact: true,
    showSymbol: true 
  });
}

/**
 * Parse currency string back to number
 * @param {string} currencyString - The currency string to parse
 * @returns {number} Parsed number value
 */
export function parseCurrency(currencyString) {
  if (!currencyString || typeof currencyString !== 'string') {
    return 0;
  }

  // Remove currency symbols and text
  const cleanString = currencyString
    .replace(/د\.إ|درهم|إماراتي|AED/g, '')
    .replace(/[^\d.-]/g, '')
    .trim();

  const parsed = parseFloat(cleanString);
  return isNaN(parsed) ? 0 : parsed;
}

/**
 * Calculate percentage with proper formatting
 * @param {number} value - Current value
 * @param {number} total - Total value
 * @returns {string} Formatted percentage
 */
export function formatPercentage(value, total) {
  if (!total || total === 0) return '0%';
  const percentage = (value / total) * 100;
  return `${Math.round(percentage)}%`;
}

/**
 * Calculate budget utilization percentage
 * @param {number} used - Used budget
 * @param {number} planned - Planned budget
 * @returns {object} Utilization data with percentage and status
 */
export function calculateBudgetUtilization(used, planned) {
  if (!planned || planned === 0) {
    return { percentage: 0, status: 'غير محدد', color: 'gray' };
  }

  const percentage = Math.round((used / planned) * 100);
  
  let status, color;
  if (percentage >= 90) {
    status = 'مرتفع';
    color = 'red';
  } else if (percentage >= 70) {
    status = 'متوسط';
    color = 'yellow';
  } else {
    status = 'منخفض';
    color = 'green';
  }

  return { percentage, status, color };
}

/**
 * Format budget variance (difference between planned and used)
 * @param {number} planned - Planned budget
 * @param {number} used - Used budget
 * @returns {object} Variance data with amount, percentage, and status
 */
export function calculateBudgetVariance(planned, used) {
  const variance = planned - used;
  const variancePercentage = planned > 0 ? Math.round((variance / planned) * 100) : 0;
  
  const isOverBudget = variance < 0;
  const status = isOverBudget ? 'تجاوز الميزانية' : 'ضمن الميزانية';
  const color = isOverBudget ? 'red' : 'green';

  return {
    amount: Math.abs(variance),
    percentage: Math.abs(variancePercentage),
    isOverBudget,
    status,
    color,
    formattedAmount: formatCurrencyDisplay(Math.abs(variance))
  };
}

/**
 * Calculate cost per beneficiary
 * @param {number} totalCost - Total cost
 * @param {number} beneficiaries - Number of beneficiaries
 * @returns {string} Formatted cost per beneficiary
 */
export function calculateCostPerBeneficiary(totalCost, beneficiaries) {
  if (!beneficiaries || beneficiaries === 0) {
    return formatCurrencyDisplay(0);
  }
  
  const costPerBeneficiary = totalCost / beneficiaries;
  return formatCurrencyDisplay(costPerBeneficiary);
}

/**
 * Generate financial summary for reports
 * @param {Array} initiatives - Array of initiatives
 * @returns {object} Financial summary object
 */
export function generateFinancialSummary(initiatives) {
  const totalPlanned = initiatives.reduce((sum, init) => sum + (init.planned_budget || 0), 0);
  const totalUsed = initiatives.reduce((sum, init) => sum + (init.used_budget || 0), 0);
  const totalRemaining = totalPlanned - totalUsed;
  
  const utilization = calculateBudgetUtilization(totalUsed, totalPlanned);
  const variance = calculateBudgetVariance(totalPlanned, totalUsed);
  
  const averageCostPerInitiative = initiatives.length > 0 ? totalUsed / initiatives.length : 0;
  
  return {
    totalPlanned: formatCurrencyDisplay(totalPlanned),
    totalUsed: formatCurrencyDisplay(totalUsed),
    totalRemaining: formatCurrencyDisplay(totalRemaining),
    utilization,
    variance,
    averageCostPerInitiative: formatCurrencyDisplay(averageCostPerInitiative),
    rawTotals: {
      planned: totalPlanned,
      used: totalUsed,
      remaining: totalRemaining
    }
  };
}

/**
 * Default currency formatter (alias for formatCurrencyDisplay)
 * @param {number} amount - The amount to format
 * @returns {string} Formatted currency string
 */
export function formatCurrency(amount) {
  return formatCurrencyDisplay(amount);
}
